scaled_dot_product_attention_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void scaled_dot_product_kernel(
    const float* __restrict__ Q,
    const float* __restrict__ K,
    const float* __restrict__ V,
    float* out,
    int B, // batch size
    int H, // number of heads
    int S, // sequence length
    int D  // embed dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * H * S) {
        int b = idx / (H * S);
        int rem = idx % (H * S);
        int h = rem / S;
        int i = rem % S;

        // Compute raw scores for this query
        float* raw_scores = new float[S];
        for (int j = 0; j < S; ++j) {
            float dot = 0.0f;
            #pragma unroll
            for (int d = 0; d < D; ++d) {
                const float q_val = Q[(b * H * S + h * S + i) * D + d];
                const float k_val = K[(b * H * S + h * S + j) * D + d];
                dot += q_val * k_val;
            }
            raw_scores[j] = dot / sqrt((float)D);
        }

        // Find max and softmax
        float max_score = -INFINITY;
        for (int j = 0; j < S; ++j) {
            if (raw_scores[j] > max_score) {
                max_score = raw_scores[j];
            }
        }
        float sum_exp = 0.0f;
        for (int j = 0; j < S; ++j) {
            float exp_val = exp(raw_scores[j] - max_score);
            raw_scores[j] = exp_val;
            sum_exp += raw_scores[j];
        }
        // Normalize
        for (int j = 0; j < S; ++j) {
            raw_scores[j] /= sum_exp;
        }

        // Weighted sum of V: out[b,h,i,:] = raw_scores * V? Actually we need weighted sum over keys:
        // O_i[d] = sum_j raw_scores[j] * V[...j,d]
        for (int j = 0; j < S; ++j) {
            for (int d = 0; d < D; ++d) {
                const float v_val = V[(b * H * S + h * S + j) * D + d];
                int out_idx = ((b * H * S + h * S + i) * D) + d;
                out[out_idx] += raw_scores[j] * v_val;
            }
        }
    }
}

torch::Tensor scaled_dot_product_attention_cuda(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    auto size = Q.numel();
    auto out = torch::zeros_like(Q);

    int B = 32;
    int H = 32;
    int S = 512;
    int D = 1024;

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    scaled_dot_product_kernel<<<num_blocks, block_size>>>(Q.data_ptr<float>(), K.data_ptr<float>(), V.data_ptr<float>(), out.data_ptr<float>(), B, H, S, D);

    return out;
}
"""

